use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k { return true }
            if x < k { cur = self.lefts[cur as usize] } else { cur = self.rights[cur as usize] }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.contains(x) { return false }
        let id = self.keys.len() as int
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        if self.root < 0 {
            self.root = id
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur as usize]
            if x < k {
                let l = self.lefts[cur as usize]
                if l < 0 { self.lefts[cur as usize] = id
                    return true }
                cur = l
            } else {
                let r = self.rights[cur as usize]
                if r < 0 { self.rights[cur as usize] = id
                    return true }
                cur = r
            }
        }
        true
    }

    fn min_node(self, n: int) -> int {
        let mut cur = n
        while self.lefts[cur as usize] >= 0 { cur = self.lefts[cur as usize] }
        cur
    }

    fn remove(self, n: int, x: int) -> int {
        if n < 0 { return -1 }
        let k = self.keys[n as usize]
        if x < k {
            let l = self.remove(self.lefts[n as usize], x)
            self.lefts[n as usize] = l
            return n
        }
        if x > k {
            let r = self.remove(self.rights[n as usize], x)
            self.rights[n as usize] = r
            return n
        }
        let l = self.lefts[n as usize]
        let r = self.rights[n as usize]
        if l < 0 { return r }
        if r < 0 { return l }
        let s = self.min_node(r)
        let sk = self.keys[s as usize]
        self.keys[n as usize] = sk
        let nr = self.remove(r, sk)
        self.rights[n as usize] = nr
        n
    }

    fn height(self, n: int) -> int {
        if n < 0 { return 0 }
        let a = self.height(self.lefts[n as usize])
        let b = self.height(self.rights[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn walk(self, n: int, out: Vec<string>) -> Vec<string> {
        if n < 0 { return out }
        let mut o = self.walk(self.lefts[n as usize], out)
        o.push("${self.keys[n as usize]}")
        self.walk(self.rights[n as usize], o)
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) {
                t.root = t.remove(t.root, x)
                println("ok")
            } else {
                println("missing")
            }
        } else if cmd == "inorder" {
            let items = t.walk(t.root, [])
            if items.len() == 0 { println("<empty>") } else { println(items.join(" ")) }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root < 0 { println("empty") } else { println("${t.keys[t.min_node(t.root) as usize]}") }
        } else if cmd == "max" {
            if t.root < 0 { println("empty") } else {
                let mut c = t.root
                while t.rights[c as usize] >= 0 { c = t.rights[c as usize] }
                println("${t.keys[c as usize]}")
            }
        }
    }
}

